-- Personas, additive: `context_mode` ('task' = the child sees only the task text; 'conversation' = it also gets a text transcript of the parent
-- conversation) and `auto_use` (0 = never offered to the chat for self-delegation; runs only on @name / /advisor, enforced at call time).
-- Seed upgrade, touching ONLY rows that still equal the old seed in EVERY field (description, tools, effort, max_tokens, model, prompt, defaults):
--   1. `advisor` is added (INSERT OR IGNORE: a user's own `advisor` is never overwritten) for scopes whose researcher AND reviewer AND summarizer all equal the seed.
--      This runs BEFORE step 2, because step 2 changes the researcher and it would no longer match.
--   2. the untouched seed `researcher` moves to claude-sonnet-5-5.
-- The two ALTERs are not re-runnable (SQLite has no ADD COLUMN IF NOT EXISTS); D1 applies each migration exactly once, so that is the repo's normal style.
ALTER TABLE personas ADD COLUMN context_mode TEXT NOT NULL DEFAULT 'task';
ALTER TABLE personas ADD COLUMN auto_use INTEGER NOT NULL DEFAULT 1;
INSERT OR IGNORE INTO personas (id, scope, name, description, prompt, model, tools_json, max_tokens, effort, context_mode, auto_use)
  SELECT lower(hex(randomblob(16))), s.scope, 'advisor', 'Senior second opinion on the conversation so far (only when you ask)',
         'You are a senior second-opinion reviewer. You are given the conversation so far and a question. Read the conversation carefully, then say what is right, what is wrong and what is missing. Name the risks and the better option if there is one. Be concise and direct. Do not redo the work and do not rewrite it. End with a clear recommendation.', 'claude-opus-5-5', NULL, 2048, 'high', 'conversation', 0
  FROM (SELECT scope FROM personas WHERE (name = 'researcher' AND description = 'Looks things up and reports the findings with sources' AND tools_json = '["read_url","search_notes","get_note"]' AND effort IS NULL AND max_tokens = 4096 AND model = 'claude-haiku-5-5' AND context_mode = 'task' AND auto_use = 1 AND prompt = 'You are a research subagent. Find the facts the task asks for using your tools, check them against more than one source when you can, and report: the answer first, then the evidence, then what you could not verify. Always name the source (URL or note title) next to each claim. Never invent a source.')
          OR (name = 'reviewer' AND description = 'Critical review of a text, plan or piece of code' AND tools_json IS NULL AND effort = 'medium' AND max_tokens = 4096 AND model = 'claude-haiku-5-5' AND context_mode = 'task' AND auto_use = 1 AND prompt = 'You are a critical reviewer subagent. List real problems first (most severe first), each with the exact quote and a concrete fix; then minor polish. Say plainly if you find nothing wrong. Do not praise filler and do not rewrite the whole thing.')
          OR (name = 'summarizer' AND description = 'Condenses long text to the essentials' AND tools_json IS NULL AND effort IS NULL AND max_tokens = 4096 AND model = 'claude-haiku-5-5' AND context_mode = 'task' AND auto_use = 1 AND prompt = 'You are a summarizing subagent. Condense the material in the task to its essentials: 3-7 bullet points, keeping names, numbers, dates and decisions; drop filler. Use the language of the material. Output only the summary.')
        GROUP BY scope HAVING COUNT(DISTINCT name) = 3) AS s;
UPDATE personas SET model = 'claude-sonnet-5-5', updated_at = datetime('now')
  WHERE (name = 'researcher' AND description = 'Looks things up and reports the findings with sources' AND tools_json = '["read_url","search_notes","get_note"]' AND effort IS NULL AND max_tokens = 4096 AND model = 'claude-haiku-5-5' AND context_mode = 'task' AND auto_use = 1 AND prompt = 'You are a research subagent. Find the facts the task asks for using your tools, check them against more than one source when you can, and report: the answer first, then the evidence, then what you could not verify. Always name the source (URL or note title) next to each claim. Never invent a source.');
